-- Everlake world import, slice 4: spawns live Forever players saw that the world lacks
-- 2026_11_08_05_world_everlake_import_slice4.sql: generated by tools/forever-data in wow-project-everlake from public WoW Forever data.
-- Sources (pins): allthethings 1528abd8252b427ad94a, eg-link 45f58b070b84501f8001, forever-db b183370ed40c718ffada, foreverdb-net 2026-11-08.816c8f61, item-history 8672fdc896ead1073a49, questiedb aa1d7e7294596cf50a6f, wago 1.60.1.70862, wowhead 2026-11-08, wowhead-tooltips parts/2026-11-08T050
-- Written against the fork world forever-tdb-2026-10-14+updates@2ae1313e9f.
-- GPL-3.0, like the rest of wow-everlake-world-data: made from GPL-3.0 forever-db (QuestieDB's spawn points, CMaNGOS heights) and CC BY 4.0 data from EG Link (Data from Efficient Games, https://efficient.games); heights without a source from Everlake's own extracted maps. Game names belong to Blizzard Entertainment.
-- Never edit this file once it is deployed (the updater would run it and every later custom file again):
-- a later fix is a new file. Running it again changes nothing: see docs/forever-import.md.

CREATE TABLE IF NOT EXISTS `everlake_import_rows` (
  `tbl` varchar(64) NOT NULL COMMENT 'world table of the row',
  `k1` bigint NOT NULL COMMENT 'the row''s key, in the table''s primary key order',
  `k2` bigint NOT NULL DEFAULT '0',
  `k3` bigint NOT NULL DEFAULT '0',
  `k4` bigint NOT NULL DEFAULT '0',
  `file` varchar(200) NOT NULL COMMENT 'the update file that added the row',
  `note` varchar(255) NOT NULL DEFAULT '' COMMENT 'the sources that gave it',
  PRIMARY KEY (`tbl`, `k1`, `k2`, `k3`, `k4`),
  KEY `file` (`file`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Rows the Everlake world import added (docs/forever-import.md)';

-- creature: spawns at points a live sighting confirms (while the fork has no spawn of the same NPC within 40 yards but ours, and never again once added: a spawn the fork removes stays removed)
DROP TEMPORARY TABLE IF EXISTS `everlake_import_stage`;
CREATE TEMPORARY TABLE `everlake_import_stage` (`guid` bigint unsigned NOT NULL, `id` int unsigned NOT NULL, `map` smallint unsigned NOT NULL, `zoneId` smallint unsigned NOT NULL, `areaId` smallint unsigned NOT NULL, `spawnDifficulties` varchar(100) NOT NULL, `phaseUseFlags` tinyint unsigned NOT NULL, `PhaseId` int, `PhaseGroup` int, `terrainSwapMap` int NOT NULL, `modelid` int unsigned NOT NULL, `equipment_id` tinyint NOT NULL, `position_x` float NOT NULL, `position_y` float NOT NULL, `position_z` float NOT NULL, `orientation` float NOT NULL, `spawntimesecs` int unsigned NOT NULL, `wander_distance` float NOT NULL, `currentwaypoint` int unsigned NOT NULL, `MovementType` tinyint unsigned NOT NULL, `VerifiedBuild` int NOT NULL, `note` varchar(255) NOT NULL, `missing` tinyint NOT NULL DEFAULT '0', PRIMARY KEY (`guid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
UPDATE `everlake_import_stage` s SET s.`missing` = 1 WHERE NOT EXISTS (SELECT 1 FROM `creature` t WHERE t.`guid` = s.`guid`) AND NOT EXISTS (SELECT 1 FROM `everlake_import_rows` r WHERE r.`tbl` = 'creature' AND r.`k1` = s.`guid`) AND NOT EXISTS (SELECT 1 FROM `creature` c WHERE c.`id` = s.`id` AND c.`map` = s.`map` AND (c.`position_x` - s.`position_x`) * (c.`position_x` - s.`position_x`) + (c.`position_y` - s.`position_y`) * (c.`position_y` - s.`position_y`) <= 1600 AND NOT EXISTS (SELECT 1 FROM `everlake_import_rows` o WHERE o.`tbl` = 'creature' AND o.`k1` = c.`guid`));
DROP TEMPORARY TABLE `everlake_import_stage`;

